			/**
			 * 그룹에서 keydown 이벤트 발생 시 호출.
			 * 사용자가 키를 누를 때 발생하는 이벤트. 키코드 관련 상수는 {@link cpr.events.KeyCode}에서 참조할 수 있습니다.
			 */
			function onGrpDataKeyup(e){
			    /**@type cpr.controls.RadioButton*/
			    var ctrl = e.control;
			    
			    // 문항에 숫자키 입력 INPUT BOX 추가 
			    var inputId = "";
			    if(ctrl.id.indexOf("inp") != -1){ // input 클릭
			        var rdbId = "rdb" + ctrl.id.replace("inp", "");
			        inputId = ctrl.id;
			        ctrl = app.lookup(rdbId);
			    } else {
			        inputId = "inp" + ctrl.id.replace("rdb", "");
			    }
			    
			    var idx = (e.code).substr(-1);
			    var radioItemCnt = ctrl.getItems().length;
			    var minVal = 0; // 최저점
			    var maxVal = 0; // 최고점
			    var dmSearch = app.lookup("dmSearch");
			    
			    /**@type cpr.controls.RadioButton*/
			    var nextCtrl = ctrl.userData("nextRadioCtrl");  
			        
			    for(var i = 0; i < ctrl.getItems().length; i++){
			        var itemVal = ctrl.getItem(i).value;
			        if(i == 0){
			            minVal = itemVal;
			            maxVal = itemVal;
			        } else {
			            if(minVal > itemVal){
			                minVal = itemVal;
			            }
			            if(maxVal < itemVal){
			                maxVal = itemVal
			            }
			        }
			    }
			    
			    if (ctrl.id == "rdb0") {
			        if (idx == "1") {
			            util.Control.setEnable(app, true, "cbg1");
			        } else {
			            util.Control.setEnable(app, false, "cbg1");
			            util.Control.setValue(app, "cbg1", "");
			        }
			    }
			    if (ctrl.id == "rdb10") {
			        if (idx == "1") {
			            util.Control.setEnable(app, true, "cbg11");
			        } else {
			            util.Control.setEnable(app, false, "cbg11");
			            util.Control.setValue(app, "cbg11", "");
			        }
			    }
			    
			    if(idx >= minVal && idx <= maxVal){
			        ctrl.value = idx;
			        app.lookup(inputId).value = idx;
			        if(!nextCtrl) return;
			        var nextInputId = "inp" + nextCtrl.id.replace("rdb", "");
			        app.lookup(nextInputId).focus();
			    } else {
			        app.lookup(inputId).value = "";
			        //util.Control.redraw(app, "grpData");
			    }
			    
			}

